# EPISODE 008: The Gospel of Judas — the book Irenaeus named around AD 180, and the Coptic copy (Codex Tchacos)
# found in Middle Egypt in the 1970s, kept in a Long Island safe deposit box, restored and published in 2006.
# Each entry: (kind, text, visual)
# Quotes (public domain only): Irenaeus, Against Heresies 1.31.1 (tr. A. Roberts & W. H. Rambaut, Ante-Nicene Fathers vol. 1,
# 1885); KJV (Matthew 26:14-15, John 13:27, Matthew 26:24).
# The Gospel of Judas itself is quoted NOWHERE: all modern translations (Kasser/Meyer/Wurst 2006-07, DeConick 2007) are
# copyrighted, so its contents are summarised in our own words.

S = [
 # ---------------------------------------------------------------- COLD OPEN
 ("vo", "Around the year one hundred and eighty, a bishop in Gaul warned his readers about a book called the Gospel of Judas.", "anf_31"),
 ("vo", "For almost eighteen hundred years, that warning was nearly all anyone knew about it. Then, in the nineteen seventies, a leather bound book came out of a cave in Egypt.", "re_224"),
 ("vo", "It spent sixteen years in a bank vault on Long Island. It fell into nearly a thousand pieces. And when scholars finally read it, they found a gospel in which Judas is the one disciple who understands.", "tis_102"),
 ("vo", "Or is he? Even the experts cannot agree.", None),
 ("title", "THE GOSPEL OF JUDAS|The Codex That Sat in a Bank Vault", "dore_085"),

 # ---------------------------------------------------------------- I
 ("chapter", "I|The Bishop's Warning", "anf_t"),
 ("vo", "The bishop was Irenaeus of Lyon. Around the year one eighty, he wrote a long work against the teachers he believed had twisted the faith.", "anf_t"),
 ("vo", "In one short passage, he describes people who honored Cain, Esau, Korah and the men of Sodom, figures the Bible remembers as rebels.", "dore_003"),
 ("vo", "And then he adds a sentence about Judas.", "dore_085"),
 ("quote", "They declare that Judas the traitor was thoroughly acquainted with these things, and that he alone, knowing the truth as no others did, accomplished the mystery of the betrayal. They produce a fictitious history of this kind, which they style the Gospel of Judas.|Irenaeus, Against Heresies 1.31.1 (tr. A. Roberts & W. H. Rambaut, Ante-Nicene Fathers, 1885)", "dore_085"),
 ("vo", "Later church writers repeated the name. But no copy was known. For centuries, the Gospel of Judas was a title and a rumor.", "dore_085"),

 # ---------------------------------------------------------------- II
 ("chapter", "II|A Book from a Cave", "re_224"),
 ("vo", "The story of the copy we have now begins in Middle Egypt, in the province of Minya, on the Nile. In the nineteen seventies, local men are said to have found a limestone box in a burial cave. Inside was a book of papyrus pages, bound in leather.", "re_224"),
 ("vo", "It was written in Coptic, the last stage of the Egyptian language, written mostly with Greek letters.", "copt_1"),
 ("vo", "In 1978, the book was sold to a dealer in Cairo, known in later reports only by a pseudonym, Hanna. Not long after, it was stolen from him, and carried out of Egypt. He recovered it in Geneva, in Switzerland.", "re_36"),
 ("vo", "In 1983, a young Coptic scholar, Stephen Emmel, was allowed to look at it in a Geneva hotel room. The pages were wrapped in newspaper, in shoe boxes. He was not allowed to take photographs.", "copt_2"),
 ("vo", "He saw enough to know it was an ancient Christian book. But the asking price was three million dollars, and the sale fell through.", "copt_2"),

 # ---------------------------------------------------------------- III
 ("chapter", "III|Sixteen Years in a Bank Vault", "tis_61"),
 ("vo", "In 1984, Hanna brought the book to the United States. When no buyer came forward, he left it in a safe deposit box at a bank in Hicksville, New York, on Long Island.", "tis_61"),
 ("vo", "It stayed there for about sixteen years. The papyrus, which had survived seventeen centuries in the dry Egyptian desert, began to crumble in the damp.", "re_168"),
 ("vo", "In the year two thousand, a Swiss antiquities dealer, Frieda Tchacos Nussberger, bought it. The codex now carries the name Tchacos, after her father.", "tis_61"),
 ("vo", "Experts at Yale identified one of its texts as the Gospel of Judas. But Yale declined to buy it, because of questions about where it had come from.", "copt_1"),
 ("vo", "A dealer in Ohio then took it, paying with post dated checks. According to later reports, he stored the papyrus in a freezer, which damaged it further. The checks were never honored, and the book went back to Tchacos.", "re_36"),
 ("vo", "In 2001, it passed to the Maecenas Foundation for Ancient Art, in Basel. By then it was in nearly a thousand fragments.", "copt_2"),

 # ---------------------------------------------------------------- IV
 ("chapter", "IV|Putting It Back Together", "copt_1"),
 ("vo", "For about five years, the restorer Florence Darbre and the Coptic scholar Gregor Wurst, working with Rodolphe Kasser, pieced the pages back together, with the help of a computer program to match the fragments.", "copt_1"),
 ("vo", "Radiocarbon tests at the University of Arizona dated the papyrus and the leather to between the years two twenty and three forty. Tests of the ink were consistent with that date.", "re_224"),
 ("vo", "The codex holds four texts: a letter of Peter to Philip, a book called James, a fragment of a work related to Allogenes, and the Gospel of Judas.", "copt_2"),
 ("vo", "On April sixth, 2006, the National Geographic Society presented the restored pages in Washington, with the first English translation. The world had heard of this gospel for eighteen centuries. Now it could read it.", "dore_085"),

 # ---------------------------------------------------------------- V
 ("chapter", "V|The Disciple Who Could Stand", "tis_81"),
 ("vo", "The book calls itself a secret account of what Jesus said to Judas Iscariot, in the days before Passover.", "tis_81"),
 ("vo", "In one early scene, the disciples are sitting together, giving thanks over bread. Jesus laughs. They do not understand, he tells them, which god they are really praising.", "dore_082"),
 ("vo", "The disciples grow angry. Jesus challenges any of them to stand before him. Only Judas can, though he cannot look him in the eye.", "tis_81"),
 ("vo", "And Judas tells Jesus where he has come from: the immortal realm of Barbelo. In this gospel, he is the only disciple who knows.", "tis_81"),
 ("vo", "Jesus then reveals a vast unseen universe: a great invisible spirit, a luminous cloud, countless angels, and lower rulers, one named Saklas, who made the world and humankind.", "dore_058"),
 ("vo", "At one point, Jesus tells Judas to lift up his eyes, and look at the cloud, and the stars around it. One of those stars, he says, is Judas's own.", "tis_62"),

 # ---------------------------------------------------------------- VI
 ("chapter", "VI|The Thirteenth", "dore_084"),
 ("vo", "In the Gospels of the New Testament, Judas is the betrayer.", "tis_61"),
 ("quote", "Then one of the twelve, called Judas Iscariot, went unto the chief priests, and said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver.|Matthew 26:14–15 (King James Version)", "tis_61"),
 ("vo", "John's Gospel goes further, and says that Satan entered into him at the supper.", "dore_082"),
 ("quote", "And after the sop Satan entered into him. Then said Jesus unto him, That thou doest, do quickly.|John 13:27 (King James Version)", "dore_082"),
 ("vo", "The Gospel of Judas tells it differently. Judas describes a vision: the twelve disciples stoning him. Jesus says that Judas will become the thirteenth, cursed by the other generations, and yet one day ruling over them.", "dore_084"),
 ("vo", "And Jesus says that Judas will go beyond all the others, because he will sacrifice the human body that Jesus wears.", "dore_083"),
 ("vo", "To the authors, the body was something the true self leaves behind. Handing it over could be read as a service.", "dore_083"),

 # ---------------------------------------------------------------- VII
 ("chapter", "VII|Hero or Demon?", "tis_105"),
 ("vo", "That was how the first translation was presented to the public: Judas as the loyal friend who did what Jesus asked.", "tis_105"),
 ("vo", "Not every scholar agreed. In 2007, April DeConick, of Rice University, argued in the New York Times that key passages had been mistranslated.", "tis_105"),
 ("vo", "Jesus calls Judas a daimon. The first translators rendered it spirit. In these Gnostic texts, DeConick argued, a daimon is a demon. On her reading, Judas is set apart from the holy generation, not for it, and the gospel is a dark parody, not a tribute.", "dore_085"),
 ("vo", "National Geographic replied that the alternatives were discussed in the notes of its editions. Other scholars, such as Elaine Pagels and Karen King, argued that the Greek verb means to hand over, not simply to betray.", "tis_102"),
 ("vo", "The debate is not settled. The same damaged pages, read with care by serious scholars, give two very different Judases.", "tis_102"),

 # ---------------------------------------------------------------- VIII
 ("chapter", "VIII|Who Wrote It?", "dore_063"),
 ("vo", "Whoever he is in its pages, Judas did not write this book. Scholars think it was composed in Greek, in the second century, more than a hundred years after the crucifixion, and later translated into Coptic.", "dore_063"),
 ("vo", "Its ideas belong to a group of early Christians that modern scholars call Sethian, who honored Adam's son Seth as the ancestor of a spiritual race.", "dore_003"),
 ("vo", "Was this the same Gospel of Judas that Irenaeus knew? Many think so, though it cannot be proven.", "anf_31"),
 ("vo", "Most scholars agree on one thing: it tells us nothing new about the historical Judas. What it reveals is how fiercely Christians of the second century argued about sacrifice, the body, and who truly understood Jesus.", "dore_067"),

 # ---------------------------------------------------------------- IX
 ("chapter", "IX|The Missing Pages", "dore_093"),
 ("vo", "The story was not quite over. Some fragments had gone missing in the years the codex was in Ohio. In 2006, a lawyer acting in the dealer's bankruptcy case announced that he held pieces of it.", "re_168"),
 ("vo", "Photographs of these Ohio fragments were finally studied, and in 2009, the scholars Marvin Meyer and Gregor Wurst presented a first reading at a meeting in New Orleans.", "copt_2"),
 ("vo", "They seem to show, near the end, Jesus rising into a cloud, while Judas is left on the ground, looking up.", "dore_093"),
 ("vo", "The gospel closes the way the old story does. Judas receives some money, and hands Jesus over.", "tis_105"),
 ("vo", "The codex was meant to return to Egypt, to the Coptic Museum in Cairo, back to the country where it was found.", "re_36"),

 # ---------------------------------------------------------------- CLOSE
 ("chapter", "|A Gospel Still Argued Over", "dore_085"),
 ("vo", "So, who is the Judas of this gospel? The one disciple who saw the truth, or a demon who served the lower powers? The words are on the page, but the page has holes.", "dore_085"),
 ("vo", "The New Testament gives its own verdict on the betrayer.", "dore_084"),
 ("quote", "The Son of man goeth as it is written of him: but woe unto that man by whom the Son of man is betrayed! it had been good for that man if he had not been born.|Matthew 26:24 (King James Version)", "dore_084"),
 ("vo", "Eighteen centuries later, a book that a bishop called fictitious came back from the desert, and asked the question again.", "re_224"),
 ("vo", "There are other lost books. The Ethiopian Bible, with eighty one books. The Infancy Gospel of Thomas, with stories of Jesus as a boy. And the Book of the Wars of the Lord, the other lost book the Bible cites.", "re_168"),
 ("vo", "If you want to hear their stories, subscribe, and tell us in the comments which one we should open next.", "re_168"),
 ("end", "THE LOST SCRIPTURES", "re_168"),
]
